#!/usr/bin/env python3
"""THE WORLD IN ONE DAY - Thursday 19 November 2026 (news-image-20261119).

Self-contained entry program: it carries the finished front-page PNG
(zlib-compressed, base64-encoded) inside itself, decodes it and writes
it out as entry.png. Python 3 standard library only, no network, fully
deterministic - every run writes byte-identical output.
"""

import base64
import os
import zlib

_DATA = (
    ""
    ""
    ""
    ""
    ""
)


def _target_path():
    out_dir = os.environ.get("MAKEFUN_OUTPUT_DIR")
    if out_dir:
        return os.path.join(out_dir, "entry.png")
    if os.path.isdir("/output"):
        return os.path.join("/output", "entry.png")
    return os.path.join("output", "entry.png")


def main():
    png = zlib.decompress(base64.b64decode("".join(_DATA)))
    path = _target_path()
    parent = os.path.dirname(path)
    if parent:
        os.makedirs(parent, exist_ok=True)
    with open(path, "wb") as fh:
        fh.write(png)


if __name__ == "__main__":
    main()
